import{_ as t,o as e,c as i,a2 as s}from"./chunks/framework.CqGPl1zp.js";const h="/newx-doc/assets/%E7%99%BE%E5%B7%9D%E6%99%BA%E8%83%BD-%E5%AE%98%E6%96%B9.C2V75LtT.png",u=JSON.parse('{"title":"【模型接入】百川智能","description":"","frontmatter":{},"headers":[],"relativePath":"ai/baichuan.md","filePath":"ai/baichuan.md","lastUpdated":null}'),n={name:"ai/baichuan.md"};function r(l,a,p,d,o,c){return e(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="【模型接入】百川智能" tabindex="-1">【模型接入】百川智能 <a class="header-anchor" href="#【模型接入】百川智能" aria-label="Permalink to &quot;【模型接入】百川智能&quot;">​</a></h1><p>项目基于 Spring AI + 自己实现的 <code>models/baichuan</code>，实现 <a href="https://www.baichuan-ai.com/" target="_blank" rel="noreferrer">百川智能</a> 的接入，底层复用兼容 OpenAI 协议的客户端：</p><table tabindex="0"><thead><tr><th>功能</th><th>模型</th><th>Spring AI 客户端</th></tr></thead><tbody><tr><td>AI 对话</td><td>Baichuan-M3-Plus、Baichuan-M3、Baichuan4-Turbo 等</td><td>BaiChuanChatModel</td></tr><tr><td>AI 绘画</td><td>暂未接入</td><td>暂未接入</td></tr><tr><td>AI 向量</td><td>Baichuan-Text-Embedding</td><td>暂未接入</td></tr></tbody></table><h2 id="_1-申请密钥" tabindex="-1">1. 申请密钥 <a class="header-anchor" href="#_1-申请密钥" aria-label="Permalink to &quot;1. 申请密钥&quot;">​</a></h2><p>百川智能历史上有<a href="https://github.com/baichuan-inc" target="_blank" rel="noreferrer">开源版本</a> ，可以按需私有化部署。</p><p>当然，我们也可以直接使用官方的 API 服务，使用也比较方便。</p><p>下面，我们来看看这两种方式怎么申请（部署）？</p><h3 id="_1-1-方式一-官方-api-申请" tabindex="-1">1.1 方式一：官方 API 申请 <a class="header-anchor" href="#_1-1-方式一-官方-api-申请" aria-label="Permalink to &quot;1.1 方式一：官方 API 申请&quot;">​</a></h3><p>① 在 <a href="https://platform.baichuan-ai.com/homePage" target="_blank" rel="noreferrer">开放平台</a> 上，注册一个账号。目前，默认注册就送 500w tokens，还是蛮爽的。</p><p>② 在 <a href="https://platform.baichuan-ai.com/console/apikey" target="_blank" rel="noreferrer">API Key 管理</a> 菜单，创建一个 API key 即可。</p><hr><p>申请完成后，可以在我们系统的 [AI 大模型 -&gt; 控制台 -&gt; API 密钥] 菜单，进行密钥的配置。只需要填写“密钥”，不需要填写“自定义 API URL”（因为 Spring AI 默认官方地址）。如下图所示：</p><p><img src="'+h+`" alt="官方的密钥配置"></p><h3 id="_1-2-方式二-私有化部署" tabindex="-1">1.2 方式二：私有化部署 <a class="header-anchor" href="#_1-2-方式二-私有化部署" aria-label="Permalink to &quot;1.2 方式二：私有化部署&quot;">​</a></h3><p>参考 <a href="https://github.com/baichuan-inc" target="_blank" rel="noreferrer">https://github.com/baichuan-inc</a> 进行部署。</p><p>当然，貌似也能用 Ollama 部署，但是我没试，可见 <a href="https://ollama.com/search?q=baichuan" target="_blank" rel="noreferrer">https://ollama.com/search?q=baichuan</a> 。</p><h3 id="_2-1-ai-对话" tabindex="-1">2.1 AI 对话 <a class="header-anchor" href="#_2-1-ai-对话" aria-label="Permalink to &quot;2.1 AI 对话&quot;">​</a></h3><p>使用 <a href="./chat">《AI 对话》</a> 时，需要在 [AI 大模型 -&gt; 控制台 -&gt; 模型配置] 菜单，配置对应的聊天模型。</p><p>不同模型的 <code>max_tokens</code>（回复数 Token 数）上限不同，可以参考下表填写：</p><table tabindex="0"><thead><tr><th>模型标识</th><th><code>max_tokens</code> 最大输出 Tokens</th></tr></thead><tbody><tr><td><code>Baichuan-M3-Plus</code></td><td>8192</td></tr><tr><td><code>Baichuan-M3</code></td><td>8192</td></tr></tbody></table><p>具体模型列表和价格，可以查看 <a href="https://platform.baichuan-ai.com/prices" target="_blank" rel="noreferrer">百川智能价格说明</a> 。</p><h3 id="_2-2-ai-绘图" tabindex="-1">2.2 AI 绘图 <a class="header-anchor" href="#_2-2-ai-绘图" aria-label="Permalink to &quot;2.2 AI 绘图&quot;">​</a></h3><p>百川暂时不支持绘图模型！！！</p><h2 id="_3-如何使用" tabindex="-1">3. 如何使用？ <a class="header-anchor" href="#_3-如何使用" aria-label="Permalink to &quot;3. 如何使用？&quot;">​</a></h2><p>① 如果你的项目里需要直接通过 <code>@Resource</code> 注入 BaiChuanChatModel 等对象，需要把 <code>application.yaml</code> 配置文件里的 <code>yudao.ai.baichuan</code> 配置项，替换成你的！</p><div class="language-YAML vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">YAML</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">yudao</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  ai</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    baichuan</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 百川智能</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      enable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      api-key</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\${BAICHUAN_API_KEY}</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Baichuan-M3</span></span></code></pre></div><p>② 如果你希望使用 [AI 大模型 -&gt; 控制台 -&gt; API 密钥] 菜单的密钥配置，则可以通过 AiModelService 的 <code>#getChatModel(...)</code> 方法，获取对应的模型对象。</p><hr><p>① 和 ② 这两者的后续使用，就是标准的 Spring AI 客户端的使用，调用对应的方法即可。</p><p>另外，BaiChuanChatModelTests 里有对应的测试用例，可以参考。</p>`,30)])])}const b=t(n,[["render",r]]);export{u as __pageData,b as default};
